      "criterion": "All existing GUI server tests (`server-*.test.ts`, `route-structured-format.test.ts`) pass without modification beyond import renames if needed.",
      "met": true
    },
    {
      "criterion": "All deprecated routes remain functional — requests to deprecated endpoints return the same responses as before the migration.",
      "met": true
    },
