1079	/**
1080	 * Iterates the route table, matches the request, conditionally parses the body,
1081	 * invokes the handler, and writes the response.
1082	 *
1083	 * Parses query parameters from the full `url` (including query string) via
1084	 * {@link parseQueryString} and passes the resulting `URLSearchParams` as the
1085	 * third argument to the matched handler.
1086	 *
1087	 * Returns `true` if a route was matched (caller should return immediately),
1088	 * or `false` if no route matched (caller should fall through).
1089	 */
1090	export async function dispatchRoute(
1091	  req: IncomingMessage,
1092	  res: ServerResponse,
1093	  method: string,
1094	  url: string,
1095	  port: number,
1096	  routes: Route[]
1097	): Promise<boolean> {
1098	  const [path] = url.split('?') as [string];
1099	  const query = parseQueryString(url);
1100	  for (const route of routes) {
1101	    if (route.method !== method) continue;
1102	    let groups: Record<string, string> | undefined;
1103	    if (typeof route.path === 'string') {
1104	      if (route.path !== path) continue;
1105	    } else {
1106	      const m = route.path.exec(path);
1107	      if (!m) continue;
1108	      groups = (m.groups ?? {}) as Record<string, string>;
1109	    }
1110	    try {
1111	      const body = route.noBody ? undefined : await readJsonBody(req);
1112	      const result = await route.handler(body, groups, query);
1113	      if (route.statusCode === 204) {
1114	        res.writeHead(204, { ...corsHeaders(port), ...securityHeaders() });
1115	        res.end();
1116	      } else {
1117	        sendJson(res, route.statusCode ?? 200, result, port);
1118	      }
1119	    } catch (err) {
1120	      if (err instanceof PayloadTooLargeError) {
1121	        sendError(res, 413, 'PAYLOAD_TOO_LARGE', 'Payload Too Large.', port);
1122	      } else if (err instanceof ApiError) {
1123	        sendError(res, apiErrorToStatus(err.code), err.code, err.message, port);
1124	      } else {
1125	        process.stderr.write(
1126	          `[server] Unhandled error in ${method} ${path}: ${String(err)}\n`
1127	        );
1128	        sendError(res, 500, 'INTERNAL_ERROR', 'An unexpected error occurred.', port);
1129	      }
1130	    }
1131	    return true;
1132	  }
1133	  return false;
1134	}
1135	
1136	// ---------------------------------------------------------------------------
1137	// Main request handler
1138	// ---------------------------------------------------------------------------
1139	
1140	export async function handleRequest(
1141	  req: IncomingMessage,
1142	  res: ServerResponse,
1143	  ledgerRoot: string,
1144	  configPath: string,
1145	  port: number,
1146	  orchestratorLogsDir: string,
1147	  bootVersions: WorkspaceVersions | null = null
1148	): Promise<void> {
1149	  const method = req.method?.toUpperCase() ?? 'GET';
1150	  const url = req.url ?? '/';

1151	  const [path] = url.split('?') as [string];
1152	  const segments = path.split('/').filter(Boolean);
1153	  const isApiRequest = segments[0] === 'api';
1154	
1155	  // OPTIONS preflight
1156	  if (method === 'OPTIONS') {
1157	    res.writeHead(200, { ...corsHeaders(port), ...securityHeaders() });
1158	    res.end();
1159	    return;
1160	  }
1161	
1162	  // Static files
1163	  if (!isApiRequest) {
1164	    await serveStatic(req, res, port);
1165	    return;
1166	  }
1167	
1168	  // All API traffic is dispatched via the unified declarative route table.
1169	  // dispatchRoute() handles both body-parsing and body-free (noBody: true) routes.
1170	  // If no route matches, fall through to 404.
1171	  if (await dispatchRoute(
1172	    req, res, method, url, port,
1173	    buildRoutes(ledgerRoot, configPath, orchestratorLogsDir, bootVersions)
1174	  )) {
1175	    return;
1176	  }
1177	
1178	  sendError(res, 404, 'NOT_FOUND', 'Route not found.', port);
1179	}
1180	
1181	// ---------------------------------------------------------------------------
1182	// Server startup
1183	// ---------------------------------------------------------------------------
1184	
1185	async function main(): Promise<void> {
1186	  const port = getPort();
1187	  const ledgerRoot = resolveLedgerRoot();
1188	  const configPath = join(ledgerRoot, 'gui-config.json');
1189	
1190	  // Populate config cache from disk (defaults used if file missing)
1191	  await readConfigFromDisk(configPath);
1192	  startConfigWatcher(configPath);
1193	
1194	  const orchestratorLogsDir = ORCHESTRATOR_LOGS_DIR;
1195	
1196	  // Capture component versions at server startup. Passed into handleRequest()
1197	  // so that subsequent GET /api/server-info calls can detect stale instances.
1198	  const bootVersions = captureWorkspaceVersions();
1199	
1200	  // Start the auto-archive background service. Reads auto_archive_days from
1201	  // config; no-op if the setting is 0.
1202	  startAutoArchiveTimer(ledgerRoot);
1203	
1204	  const server = createServer((req, res) => {
1205	    handleRequest(req, res, ledgerRoot, configPath, port, orchestratorLogsDir, bootVersions).catch((err) => {
1206	      process.stderr.write(`[server] Unhandled error: ${String(err)}\n`);
1207	      if (!res.headersSent) {
1208	        res.writeHead(500, { 'Content-Type': 'application/json', ...securityHeaders() });
1209	        res.end(
1210	          JSON.stringify({
1211	            error: { code: 'INTERNAL_ERROR', message: 'An unexpected error occurred.' },
1212	          })
1213	        );
1214	      }
1215	    });
1216	  });
1217	
1218	  server.on('error', (err: NodeJS.ErrnoException) => {
1219	    if (err.code === 'EADDRINUSE') {
1220	      process.stderr.write(
1221	        `[server] Port ${port} is already in use. Choose a different port with --port <n>. Exiting.\n`
1222	      );
1223	      process.exit(1);
1224	    }
1225	    throw err;
1226	  });
1227	
1228	  server.listen(port, () => {
1229	    console.log(`GUI dashboard running at http://localhost:${port}`);
1230	  });
1231	}
1232	
1233	// Only run main() when this file is the entry point (e.g. `tsx gui/server.ts`),
1234	// not when it is imported by test code (e.g. to access the exported handleRequest).
1235	const isEntryPoint =
1236	  process.argv[1] !== undefined &&
1237	  fileURLToPath(import.meta.url) === resolve(process.argv[1]);
1238	
